# clean_stale.ps1 - remove the leftovers that development and testing leave on this PC, and ONLY those.
#   powershell -File tools\clean_stale.ps1            # dry run: lists what would go, with sizes
#   powershell -File tools\clean_stale.ps1 -Apply     # deletes it
#   -Keep 0.18.0,0.17.0   release versions whose zips in dist\ are kept (default: none; the current build is
#                         always kept by passing its version)
#   -Build                also removes the build\ export folders (regenerated by tools\build_release.ps1)
# It only ever touches paths that match the allowlists below. It NEVER touches: .godot (the import cache),
# assets\fonts (the licensed font is not in git), audio\music\*.wav (the music source), version.txt, any
# source file, the owner's saves, or other programs' folders. It never stops a process.
param([switch]$Apply, [string[]]$Keep = @(), [switch]$Build)
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
$total = 0
$count = 0
function SizeOf($p) {
    if (Test-Path -LiteralPath $p -PathType Container) { (Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum }
    else { (Get-Item -LiteralPath $p -Force).Length }
}
function Drop($p, $why) {
    $s = [int64](SizeOf $p)
    $script:total += $s
    $script:count++
    if ($Apply) {
        try { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop }
        catch { Write-Host ("  [kept: in use or locked] {0}" -f $p); $script:total -= $s; $script:count-- ; return }
    }
    if ($script:count -le 25 -or $s -gt 20MB) { Write-Host ("  {0,8:n1} MB  {1}  ({2})" -f ($s / 1MB), $p, $why) }
}

# 1. Temp folders and logs from test and capture runs (the names this project's tools create)
$prefix = '^(ap_|ascent_gate_|ascent_clean_|ascent_e2e_|ascent_update_rules|some_test_|b_test_)'
Get-ChildItem $env:TEMP -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $prefix } | ForEach-Object { Drop $_.FullName "temp test leftover" }

# 2. Caches in the project that are recreated on demand
foreach ($rel in ".pytest_cache", "launcher\.pytest_cache", "launcher\__pycache__", "launcher\tests\__pycache__", "tools\__pycache__") {
    $p = Join-Path $root $rel
    if (Test-Path -LiteralPath $p) { Drop $p "cache" }
}
$cap = Join-Path $root ".cap"
if (Test-Path -LiteralPath $cap) { Get-ChildItem $cap -Force | ForEach-Object { Drop $_.FullName "capture output" } }

# 3. Old release builds in dist\ (published releases and git history hold every shipped build)
$dist = Join-Path $root "dist"
if (Test-Path -LiteralPath $dist) {
    # Everything in dist\ is a build output. What stays: the kept versions' release files and the current launcher.
    # Folders are staging copies that the release script recreates; every other file is an old log or picture.
    Get-ChildItem $dist -Force | ForEach-Object {
        $isKept = $false   # (not $keep: variable names are case-insensitive and that would overwrite the -Keep parameter)
        if (-not $_.PSIsContainer) {
            if ($_.Name -eq "ProjectAscentLauncher.exe") { $isKept = $true }
            foreach ($v in $Keep) { if ($_.Name -like "Project-Ascent-v$v-*" -or $_.Name -like "Project-Ascent-v$v.*") { $isKept = $true } }
        }
        if (-not $isKept) { Drop $_.FullName $(if ($_.PSIsContainer) { "staging copy or old output" } elseif ($_.Name -match '^Project-Ascent-v') { "old release build" } else { "old log or picture" }) }
    }
}
if ($Build) {
    $b = Join-Path $root "build"
    if (Test-Path -LiteralPath $b) { Get-ChildItem $b -Force | ForEach-Object { Drop $_.FullName "build output" } }
}
Write-Host ("{0}: {1} item(s), {2:n1} MB" -f $(if ($Apply) { "removed" } else { "would remove (dry run, add -Apply)" }), $count, ($total / 1MB))
